//! Chrome-156 control for the HTML drive's document model (miaskiewicz/turbo-html2pdf#29):
//! `<head>` styles apply, `<html>`/`<body>` are real boxes with Chrome's UA semantics
//! (`body { margin: 8px }`, root margins never collapse, `rem` against the root font size)
//! and the root/body background is propagated to the canvas. P5b-W1 adds conditional-rule
//! source order (miaskiewicz/turbo-dom#24 item 1).
//!
//! Reads `tests/fixtures/html_document_chrome156.json` (generated by turbo-dom's
//! `scripts/html-document-chrome-control.mjs`) and lays every case out through
//! [`layout_boxes`] (the `data-cid` geometry seam of `layout_html`) at Chrome's 1280x800
//! viewport, comparing each box with Chrome's `getBoundingClientRect()`, and the galley
//! root's background (the canvas) with Chrome's canvas pixel.
use serde_json::Value;
use turbo_dom_layout::{
    layout_boxes, layout_html, Diagnostics, FontRegistry, FragmentContent, Rgba,
};

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/html_document_chrome156.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("the Chrome fixture")).unwrap()
}

/// The canvas colour as painted: `c` over the white initial canvas.
fn hex(c: Rgba) -> String {
    let a = u32::from(c.a);
    let mix = |v: u8| (u32::from(v) * a + 255 * (255 - a) + 127) / 255;
    format!("#{:02x}{:02x}{:02x}", mix(c.r), mix(c.g), mix(c.b))
}

/// Lay out every fixture case `select` picks and compare it with Chrome.
fn compare_cases(select: impl Fn(&str) -> bool) {
    let fixture = fixture();
    let fonts = FontRegistry::new();
    let mut failures = Vec::new();
    let cases = fixture["cases"].as_array().unwrap();
    let mut compared = 0;
    for case in cases {
        let id = case["id"].as_str().unwrap();
        if !select(id) {
            continue;
        }
        compared += 1;
        let html = case["html"].as_str().unwrap();
        let measure = case["measure"].as_str().unwrap();
        let mut diags = Diagnostics::default();
        let got = layout_boxes(html, "", 1280.0, 800.0, &fonts, &mut diags).unwrap();
        for want in case["boxes"].as_array().unwrap() {
            let cid = want["cid"].as_str().unwrap();
            let Some(b) = got.iter().find(|b| b.cid == cid) else {
                failures.push(format!("{id}: no box for data-cid={cid}"));
                continue;
            };
            for (key, value) in [("x", b.x), ("y", b.y), ("w", b.width), ("h", b.height)] {
                if !measure.contains(key) {
                    continue;
                }
                let field = match key {
                    "w" => "width",
                    "h" => "height",
                    k => k,
                };
                let chrome = want[field].as_f64().unwrap() as f32;
                if (value - chrome).abs() > 0.01 {
                    failures.push(format!("{id}: {cid}.{field} = {value}, Chrome {chrome}"));
                }
            }
        }
        let mut diags = Diagnostics::default();
        let galley = layout_html(html, "", 1280.0, &fonts, &mut diags).unwrap();
        let canvas = match &galley.content {
            FragmentContent::Box {
                background: Some(c),
                ..
            } => hex(*c),
            _ => "#ffffff".to_string(),
        };
        if canvas != case["canvas"].as_str().unwrap() {
            failures.push(format!("{id}: canvas {canvas}, Chrome {}", case["canvas"]));
        }
    }
    assert!(compared > 0);
    assert!(
        failures.is_empty(),
        "{} of {compared} cases differ from Chrome 156:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The miaskiewicz/turbo-dom#28 item 7 cases (`width: auto` tables shrink to fit on the
/// HTML path), held out of [`html_documents_lay_out_as_chrome_156`] until the fix lands.
fn auto_table_case(id: &str) -> bool {
    id.starts_with("table-auto-")
}

/// miaskiewicz/turbo-dom#53: `inline-flex` / `inline-grid` are atomic inline-level boxes.
fn inline_flex_grid_case(id: &str) -> bool {
    id.starts_with("inline-flex-") || id.starts_with("inline-grid-")
}

/// The control cases of an open bug, each asserted by its own test (`#[ignore]`d until
/// its fix lands) and held out of [`html_documents_lay_out_as_chrome_156`].
fn held_out(id: &str) -> bool {
    let groups: [fn(&str) -> bool; 30] = [
        auto_table_case,
        inline_flex_grid_case,
        abs_auto_width_case,
        percent_column_case,
        collapsed_auto_case,
        colspan_case,
        caption_case,
        border_box_case,
        table_border_box_case,
        spacing_case,
        table_height_case,
        column_growth_case,
        last_margin_case,
        legacy_align_case,
        th_case,
        min_height_margin_case,
        zero_area_clip_case,
        min_max_height_case,
        percent_height_case,
        self_collapsing_first_child_case,
        intrinsic_margin_case,
        inline_block_margin_case,
        icb_case,
        flow_root_case,
        float_shrink_case,
        intrinsic_oof_case,
        abs_stretch_case,
        column_flex_case,
        float_sum_case,
        flex_item_box_sizing_case,
    ];
    groups.iter().any(|group| group(id))
}

#[test]
fn html_documents_lay_out_as_chrome_156() {
    compare_cases(|id| !held_out(id));
}

#[test]
fn inline_flex_and_grid_are_inline_level_like_chrome_156() {
    compare_cases(inline_flex_grid_case);
}

#[test]
fn auto_width_tables_shrink_to_fit_like_chrome_156() {
    compare_cases(auto_table_case);
}

